/* Minimal Fun module (fun.min.js): detectmobile only
 * - Exposes Fun.detectmobile with these properties:
 *   - isMobile, isIPhone, isIPad, isIosChrome, fbApp
 * - No dependency on jQuery (pure web APIs)
 */
var Fun = (function() {
    'use strict';
    var funObj = {};

    funObj.detectmobile = {
        isMobile: false,
        isIPhone: false,
        isIPad: false,
        isIosChrome: false,
        fbApp: undefined
    };

    var ua = (navigator.userAgent || '').toLowerCase();
    var MOBILES_NAME = ['android','iphone','windows ce','windows phone','symbian','blackberry','mobile','phone','midp','cldc','opera mini','minimo','up.browser','up.link','docomo','avantgo','palmos','ppc','xv6850','htc_','kindle','wap','mmp/','teleca','lge','portalmmm','nintendo','nokia','armv','j2me','nook browser','webos','blazer','epoc','samsung','novarra-vision','netfront','sec-sgh','sharp','au-mic/1.1.4.0','reqwirelessweb','sonyericsson','playstation','vodafone','ucweb'];

    for (var a = 0, len = MOBILES_NAME.length; a < len; a++) {
        if (ua.indexOf(MOBILES_NAME[a]) !== -1) {
            funObj.detectmobile.isMobile = true;
            break;
        }
    }
    if (ua.indexOf('iphone') > -1) funObj.detectmobile.isIPhone = true;
    if (ua.indexOf('ipad') > -1) funObj.detectmobile.isIPad = true;
    if (ua.indexOf('fbav') !== -1) {
        if (ua.indexOf('fb_iab') !== -1 || ua.indexOf('fb4a') !== -1) {
            funObj.detectmobile.fbApp = 'android';
        } else if (ua.indexOf('fban') !== -1 || ua.indexOf('fbios') !== -1) {
            funObj.detectmobile.fbApp = 'ios';
        }
    }
    if (funObj.detectmobile.isIPhone || funObj.detectmobile.isIPad) {
        if (ua.indexOf('crios') > -1) funObj.detectmobile.isIosChrome = true;
    }

    funObj.detectmobile.isMobileHeuristic = function(maxWidth) {
        maxWidth = typeof maxWidth === 'number' ? maxWidth : 767;
        if (navigator.userAgentData && typeof navigator.userAgentData.mobile === 'boolean') {
            return navigator.userAgentData.mobile;
        }
        var touchCapable = !!('ontouchstart' in window) || (navigator.maxTouchPoints && navigator.maxTouchPoints > 0) || (navigator.msMaxTouchPoints && navigator.msMaxTouchPoints > 0);
        var isSmallScreen = window.matchMedia && window.matchMedia('(max-width: ' + maxWidth + 'px)').matches;
        if (funObj.detectmobile.isMobile || (touchCapable && isSmallScreen)) return true;
        return false;
    };

    return funObj;
})();

// Expose as a browser global for scripts that expect `Fun` on window
if (typeof window !== 'undefined') {
    window.Fun = Fun;
}
// CommonJS / Node
if (typeof module !== 'undefined' && module.exports) {
    module.exports = Fun;
}
